#include <iostream>
#include <vector>
#include <algorithm>
#include <string>
#include <chrono>
#include <random>
using namespace std;

struct ResData { int waysCount, sumAdd; ResData() : waysCount(0), sumAdd(0) {} ResData(int w, int s) : waysCount(w), sumAdd(s) {} };

int totalComponents, totalPersons, MOD;
vector<vector<int>> binomial;

int sumInterval(int a, int b) { return (a + b) * (b - a + 1) / 2; }

vector<bool> visitedStates2;
vector<ResData> cacheStates2;

ResData computeStates2(int n) {
    if (n == 1) return ResData(2, 0);
    if (visitedStates2[n]) return cacheStates2[n];
    ResData result(0, 0);
    for (int i = 0; i < n; ++i) {
        int leftSize = i, rightSize = n - i - 1;
        ResData leftRes = (leftSize == 0) ? ResData(1, 0) : computeStates2(leftSize);
        ResData rightRes = (rightSize == 0) ? ResData(1, 0) : computeStates2(rightSize);
        int totalWays = (leftSize + 1) + (rightSize + 1);
        int totalSum = sumInterval(0, leftSize) + sumInterval(0, rightSize);
        int mlt = binomial[leftSize + rightSize][leftSize];
        result.waysCount = (result.waysCount + (long long)leftRes.waysCount * totalWays % MOD * rightRes.waysCount) % MOD;
        result.sumAdd = (result.sumAdd + (long long)leftRes.sumAdd * totalWays % MOD * rightRes.waysCount
                         + (long long)leftRes.waysCount * totalSum % MOD * rightRes.waysCount
                         + (long long)leftRes.waysCount * totalWays % MOD * rightRes.sumAdd) % MOD;
    }
    visitedStates2[n] = true;
    cacheStates2[n] = result;
    return result;
}

vector<vector<bool>> visitedStates1;
vector<vector<ResData>> cacheStates1;

ResData computeStates1(int index, int count) {
    if (totalComponents - index == count) return computeStates2(count);
    if (visitedStates1[index][count]) return cacheStates1[index][count];
    ResData res(0, 0);
    for (int i = index; i < totalComponents; ++i) {
        int leftCount = i - index;
        int rightCount = count - leftCount;
        if (rightCount < 0 || rightCount > totalComponents - i - 1) continue;
        ResData leftRes = (i == index) ? ResData(1, 0) : computeStates2(leftCount);
        ResData rightRes = (i + 1 == totalComponents) ? ResData(1, 0) : computeStates1(i + 1, rightCount);
        int mlt = binomial[leftCount + rightCount][leftCount];
        res.waysCount = (res.waysCount + (long long)leftRes.waysCount * rightRes.waysCount % MOD * mlt) % MOD;
        res.sumAdd = (res.sumAdd + (long long)leftRes.sumAdd * rightRes.waysCount % MOD * mlt
                      + (long long)leftRes.waysCount * rightRes.sumAdd % MOD * mlt) % MOD;
    }
    visitedStates1[index][count] = true;
    cacheStates1[index][count] = res;
    return res;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int ncomp, npers, MOD;
    cin >> ncomp >> npers >> MOD;
    totalComponents = ncomp;
    totalPersons = npers;
    ::MOD = MOD;
    binomial.assign(ncomp + 1, vector<int>(ncomp + 1, 0));
    for (int i = 0; i <= ncomp; ++i) {
        binomial[i][0] = 1;
        binomial[i][i] = 1;
        for (int j = 1; j < i; ++j) {
            binomial[i][j] = (binomial[i - 1][j - 1] + binomial[i - 1][j]) % MOD;
        }
    }
    visitedStates2.assign(ncomp + 1, false);
    cacheStates2.assign(ncomp + 1, ResData());
    visitedStates1.assign(ncomp + 1, vector<bool>(npers + 1, false));
    cacheStates1.assign(ncomp + 1, vector<ResData>(npers + 1));
    cout << computeStates1(0, npers).sumAdd << "\n";
    return 0;
}
